```typescript
import { type Plugin, tool } from "@opencode-ai/plugin";
import { homedir } from "node:os";

const STATE_PATH = `${homedir()}/.local/share/opencode/phase0-state.json`;
const DB_PATH = `${homedir()}/.local/share/opencode/opencode.db`;
const MEMORY_SESSIONS = `${homedir()}/.local/share/opencode/memory/sessions`;

const PHASE0_ALLOWED = new Set(["memory_search", "skill", "read", "phase0_complete"]);
const CHECKPOINT_MIN_MSGS = 30;
const CHECKPOINT_ALLOWED = new Set(["task", "memory_search", "read", "skill", "checkpoint_done"]);

const AGENTS_CACHE_TTL = 30_000; // 30 seconds

interface State {
  cycle1Completed: boolean;
  sessionId: string | null;
  cpCache: Record<string, { messageCount: number; checkpointExists: boolean; lastChecked: number }>;
}

export default (async ({ $, client }) => {
  const sh = $;

  // Load state
  let state: State = {
    cycle1Completed: false,
    sessionId: null,
    cpCache: {},
  };

  try {
    const f = Bun.file(STATE_PATH);
    if (await f.exists()) {
      state = { ...state, ...JSON.parse(await f.text()) };
      state.cpCache = {};
    }
  } catch {}

  async function persist() {
    try {
      await Bun.write(STATE_PATH, JSON.stringify({ ...state, cpCache: {} }, null, 2));
    } catch (e) {
      void client.app.log({ body: { service: "phase0-guard", level: "error", message: `persist: ${e}` } });
    }
  }

  // === Agent permission cache via API ===
  let agentsCache: any[] | null = null;
  let agentsCacheTime = 0;

  async function getAgentsFromAPI(): Promise<any[]> {
    const now = Date.now();
    if (agentsCache && now - agentsCacheTime < AGENTS_CACHE_TTL) {
      return agentsCache;
    }
    try {
      const agents = await client.app.agents();
      agentsCache = agents;
      agentsCacheTime = now;
      return agents;
    } catch (e) {
      void client.app.log({ body: { service: "phase0-guard", level: "error", message: `agents api: ${e}` } });
      return agentsCache || [];
    }
  }

  function isToolDeniedForAgent(toolName: string, agentId: string, agents: any[]): boolean {
    const agent = agents.find((a: any) => a.name === agentId);
    if (!agent) return false; // неизвестный агент — не блокируем (чтобы не сломать сабагентов)

    // deny через tools { toolName: false }
    if (agent.tools && agent.tools[toolName] === false) return true;
    if (agent.tools) {
      for (const [key, allowed] of Object.entries(agent.tools)) {
        if (typeof allowed === 'boolean' && !allowed) {
          if (key.endsWith('*') && toolName.startsWith(key.slice(0, -1))) return true;
          if (key.startsWith('*') && toolName.endsWith(key.slice(1))) return true;
          if (key === toolName) return true;
        }
      }
    }

    // deny через permission: edit: "deny", bash.*: "deny", etc
    if (agent.permission) {
      for (const [key, rule] of Object.entries(agent.permission)) {
        if (rule === "deny") {
          if (key === toolName) return true;
          if (key.endsWith('*') && toolName.startsWith(key.slice(0, -1))) return true;
        }
        if (typeof rule === 'object' && rule !== null) {
          for (const [pat, action] of Object.entries(rule)) {
            if (action === "deny") {
              if (pat === toolName || pat === '*') return true;
              if (pat.endsWith('*') && toolName.startsWith(pat.slice(0, -1))) return true;
            }
          }
        }
      }
    }

    return false;
  }

  // === Agent resolution from session ===
  async function getAgentForSession(sessionID: string): Promise<string | null> {
    try {
      const r = await sh`sqlite3 ${DB_PATH} "SELECT agent_id FROM session WHERE id = '${sessionID.replace(/'/g, "''")}'"`.quiet().nothrow();
      return r.stdout?.toString().trim() || null;
    } catch {
      return null;
    }
  }

  // === Session ID resolution ===
  async function getCurrentSessionId(): Promise<string | null> {
    if (state.sessionId) return state.sessionId;
    try {
      const r = await sh`sqlite3 ${DB_PATH} "SELECT id FROM session WHERE parent_id IS NULL ORDER BY time_updated DESC LIMIT 1"`.quiet().nothrow();
      const sid = r.stdout?.toString().trim() || null;
      if (sid) state.sessionId = sid;
      return sid;
    } catch {
      return null;
    }
  }

  // === Checkpoint helpers ===
  async function getMessageCount(sessionId: string): Promise<number> {
    const cache = state.cpCache[sessionId];
    const now = Date.now();
    if (cache && now - cache.lastChecked < 10_000) return cache.messageCount;
    try {
      const r = await sh`sqlite3 ${DB_PATH} "SELECT COUNT(*) FROM message WHERE session_id = '${sessionId.replace(/'/g, "''")}'"`.quiet().nothrow();
      const count = parseInt(r.stdout?.toString().trim() || "0");
      const existing = state.cpCache[sessionId] || { checkpointExists: false, lastChecked: 0 };
      state.cpCache[sessionId] = { ...existing, messageCount: count, lastChecked: now };
      return count;
    } catch { return 0; }
  }

  async function checkpointFileExists(sessionId: string): Promise<boolean> {
    const cache = state.cpCache[sessionId];
    const now = Date.now();
    if (cache && now - cache.lastChecked < 10_000) return cache.checkpointExists;
    try {
      const cpPath = `${MEMORY_SESSIONS}/${sessionId}/checkpoint.md`;
      const f = Bun.file(cpPath);
      const exists = await f.exists();
      const ok = exists && (await f.text()).trim().length > 0;
      const existing = state.cpCache[sessionId] || { messageCount: 0, lastChecked: 0 };
      state.cpCache[sessionId] = { ...existing, checkpointExists: ok, lastChecked: now };
      return ok;
    } catch { return false; }
  }

  return {
    tool: {
      phase0_complete: tool({
        description: "Подтвердить выполнение CYCLE 1. Снимает Phase 0 guard.",
        args: {},
        async execute() {
          state.cycle1Completed = true;
          await persist();
          return "✅ Phase 0 guard снят.";
        },
