      checkpoint_done: tool({
        description: "Подтвердить запись checkpoint. Снимает Checkpoint Gate.",
        args: {},
        async execute() {
          const sid = await getCurrentSessionId();
          if (sid) {
            state.cpCache[sid] = { messageCount: 999, checkpointExists: true, lastChecked: Date.now() };
            await persist();
          }
          return "✅ Checkpoint Gate снят.";
        },
      }),
    },

    "tool.execute.before": async (input, output) => {
      try {
        // === Phase 0 Guard — only for jarvis ===
        const isJarvis = state.sessionId && input.sessionID === state.sessionId;
        // Actually this is wrong. Need better detection.
