          if (!PHASE0_ALLOWED.has(input.tool)) {
            output.args = undefined; // prevent execution
            // Hmm, output.args = undefined might not block execution
            // Need to throw or use error response
          }
        }
      } catch (e) {}
    },
  };
}) satisfies Plugin;
