```typescript
import { type Plugin, tool } from "@opencode-ai/plugin";

interface AgentDeny {
  toolNames: string[];        // точное совпадение
  prefixPatterns: string[];   // те что с *
}

export default (async ({ client }) => {
  // === Load agent permissions ===
  let denyByAgent: Record<string, AgentDeny> = {};
  let loaded = false;

  async function loadPermissions() {
    try {
      const agents = await client.app.agents();
      denyByAgent = {};

      for (const agent of agents) {
        const denies: AgentDeny = { toolNames: [], prefixPatterns: [] };

        // Check agent.tools (булевы значения)
        if (agent.tools) {
          for (const [toolName, allowed] of Object.entries(agent.tools)) {
            if (allowed === false) {
              if (toolName.endsWith('*')) {
                denies.prefixPatterns.push(toolName.slice(0, -1));
              } else {
                denies.toolNames.push(toolName);
              }
            }
          }
        }

        // Check agent.permission (deny/allow)
        if (agent.permission) {
          for (const [key, rule] of Object.entries(agent.permission)) {
            if (rule === "deny") {
              if (key.endsWith('*')) {
                denies.prefixPatterns.push(key.slice(0, -1));
              } else {
                denies.toolNames.push(key);
              }
            }
            if (typeof rule === 'object' && rule !== null) {
              for (const [pat, action] of Object.entries(rule)) {
                if (action === "deny") {
                  if (pat.endsWith('*')) denies.prefixPatterns.push(pat.slice(0, -1));
                  else denies.toolNames.push(pat);
                }
              }
            }
          }
        }

        denyByAgent[agent.name] = denies;
      }

      loaded = true;
    } catch (e) {
      void client.app.log({ body: { service: "phase0-guard", level: "error", message: `load: ${e}` } });
    }
  }

  // Initial load
  await loadPermissions();

  // Periodic reload
  setInterval(loadPermissions, 30_000);

  function isToolDenied(toolName: string, agentName: string): boolean {
    const denies = denyByAgent[agentName];
    if (!denies) return false;

    if (denies.toolNames.includes(toolName)) return true;
    for (const prefix of denies.prefixPatterns) {
      if (toolName.startsWith(prefix)) return true;
    }
    return false;
  }

  return {
    config: (cfg) => {
      if (!loaded) return;

      // Для каждого существующего агента модифицируем tools
      for (const [agentName, agentCfg] of Object.entries(cfg.agent || {})) {
        const denies = denyByAgent[agentName];
        if (!denies || (denies.toolNames.length === 0 && denies.prefixPatterns.length === 0)) continue;

        // Инициализируем tools если нет
        if (!agentCfg.tools) agentCfg.tools = {};

        // Устанавливаем false для запрещённых
        for (const name of denies.toolNames) {
          agentCfg.tools[name] = false;
        }
      }
    },

    // Пока не нужно, но заготовка
    // tool: { ... }
  };
}) satisfies Plugin;
```

